/* 0075_niche_counts_in_one_query.sql, flattened for the Supabase SQL editor. Generated by scripts/flatten-migration.mjs - do not edit this file, edit the migration and run the script again. One statement per line, no line comments, nothing to lose to a newline. The commentary lives in the migration itself. */
create or replace function public.marketplace_niche_counts() returns table (niche text, listings bigint) language sql stable security definer set search_path = public as $$ select c.slug as niche, count(*) as listings from public.websites w join public.categories c on c.id = w.primary_category_id where w.status = 'active' group by c.slug; $$;
comment on function public.marketplace_niche_counts() is 'How many active listings sit in each primary category. Replaces reading every active listing and counting them in JavaScript - seven sequential requests to draw the homepage''s niche cards.';
revoke all on function public.marketplace_niche_counts() from public;
grant execute on function public.marketplace_niche_counts() to anon, authenticated, service_role;
